	const model = fallback.harness === harness ? fallback.model : (items[0]?.value ?? "");
	return { harness, model, effort: clampEffort(harness, providers, model, role.effort) };
}

/** 추가할 모델 하나: 주 모델과 이미 고른 모델을 빼고, 주 모델의 하네스에서 아직 안 쓴 모델을 고른다.
 *  그 하네스가 다 썼으면 반대 하네스로 넘어간다. 없으면 추가할 수 없다. */
export function nextFallback(primary: RoleModel, taken: RoleModel[], providers: PiProvider[]): RoleModel | null {
