/**
 * The task a harness is working on, read from the terminal title it sets.
 * Idle titles (Claude Code's own name, pi with no session) are null.
 *
 * - claude: `✳ topic` / `⠂ topic`. The leading spinner glyph is not part of the topic.
 * - pi: `{app} - {session} - {folder}`. The session may itself contain ` - `.
 *   `{app} - {folder}` has no session.
 */
import type { Harness } from "./harness.js";

const CLAUDE_IDLE = "Claude Code";
/** One leading spinner glyph (✳, braille ⠂, …) and the space after it. */
const SPINNER = /^\p{So}\s*/u;

export function taskTitle(harness: Harness, title: string): string | null {
	if (harness === "claude") {
		const topic = title.replace(SPINNER, "").trim();
		return topic && topic !== CLAUDE_IDLE ? topic : null;
	}
	const parts = title.split(" - ");
	if (parts.length < 3) return null;
	const session = parts.slice(1, -1).join(" - ").trim();
	return session || null;
}

